import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Event Publishers","description":"","frontmatter":{},"headers":[],"relativePath":"events/event-publishers.md","filePath":"events/event-publishers.md"}`),a={name:`events/event-publishers.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="event-publishers" tabindex="-1">Event Publishers <a class="header-anchor" href="#event-publishers" aria-label="Permalink to “Event Publishers”">​</a></h1><p>An <strong>event publisher</strong> is an AL object (such as a codeunit, table or page) that declares an event, making it available for other objects to subscribe to.</p><p>In Business Central, Integration Events and Business Events are published using event publisher procedures.</p><h2 id="creating-an-event-publisher" tabindex="-1">Creating an Event Publisher <a class="header-anchor" href="#creating-an-event-publisher" aria-label="Permalink to “Creating an Event Publisher”">​</a></h2><p>An event publisher is an ordinary AL procedure decorated with an event attribute.</p><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 CustomerEvents</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [IntegrationEvent(false, false)]</span></span>
<span class="line"><span>    procedure OnCustomerCreated(CustomerNo: Code[20])</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ul><li><code>[IntegrationEvent(false, false)]</code> identifies the procedure as an Integration Event publisher.</li><li><code>OnCustomerCreated</code> is the event name.</li><li><code>CustomerNo</code> is a parameter passed to subscribers.</li></ul><p>You can also use <code>[BusinessEvent(false)]</code> to declare a Business Event.</p><h2 id="publishing-vs-raising-an-event" tabindex="-1">Publishing vs Raising an Event <a class="header-anchor" href="#publishing-vs-raising-an-event" aria-label="Permalink to “Publishing vs Raising an Event”">​</a></h2><p>These are two different operations.</p><p><strong>Publishing:</strong> Declaring the event using an event publisher procedure makes it available for subscription.</p><p><strong>Raising:</strong> Calling the publisher procedure triggers the event and executes its subscribers.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    CustomerEvents: Codeunit CustomerEvents;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    CustomerEvents.OnCustomerCreated(Rec.&quot;No.&quot;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>When this procedure is called, all subscribers listening to that event are executed.</p><p><strong>Important:</strong> Declaring an event does not automatically trigger it. You must explicitly call the publisher procedure.</p><h2 id="important-rules" tabindex="-1">Important Rules <a class="header-anchor" href="#important-rules" aria-label="Permalink to “Important Rules”">​</a></h2><ul><li>Event publisher procedures must not contain business logic; their bodies should be empty.</li><li>They cannot have return values or local variables.</li><li>They can accept parameters, which provide information to subscribers.</li><li>You can declare publishers in codeunits, tables, pages and other AL objects.</li><li>Multiple subscribers can listen to the same event.</li><li>A publisher does not need to know whether any subscribers exist.</li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>Publishing an event exposes an extension point. Raising the event invokes the subscribers listening to that extension point.</p><p>Remember the sequence:</p><p><strong>Publish → Raise → Subscribers execute.</strong></p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};